<template>
  <NuxtPage />
  <div v-if="!viewingDetail" class="content-store-page">
    <header class="store-header"><div><NuxtLink to="/" class="back-link">Back to channels</NuxtLink><h1>Content Store</h1><p>Find published channel building blocks, prove what is included, then own and install them deliberately. Packs are permanently owned by your GenStudio account.</p></div><div class="store-header-actions"><button type="button" class="btn btn-secondary" :disabled="loading" @click="restoreOwnership">Restore purchases</button><button type="button" class="btn btn-secondary" :disabled="loading" @click="loadStore">{{ loading ? 'Refreshing…' : 'Refresh store' }}</button></div></header>
    <section v-if="account" class="account-strip" aria-label="Content Store account balances"><div><span>Content account</span><strong>{{ account.contentAccountId }}</strong></div><dl><div><dt>Spendable on content</dt><dd>{{ formatCredits(account.contentSpendableCredits) }} credits</dd></div><div><dt>Total available</dt><dd>{{ formatCredits(account.availableCredits) }} credits</dd></div></dl></section>
    <div v-if="pageError" :class="['store-notice', pageError.tone]" role="status"><div><strong>{{ pageError.title }}</strong><p>{{ pageError.detail }}</p><button v-if="pageError.showSettings" type="button" class="notice-action" @click="appSettingsModal.open()">Open Settings and test scopes</button></div></div>
    <nav class="store-tabs" role="tablist" aria-label="Content Store views" @keydown="moveTab"><button v-for="tab in tabs" :id="`content-store-tab-${tab.id}`" :key="tab.id" :ref="element => setTabRef(tab.id, element)" type="button" role="tab" :aria-selected="activeTab === tab.id" :aria-controls="`content-store-panel-${tab.id}`" :tabindex="activeTab === tab.id ? 0 : -1" @click="activeTab = tab.id">{{ tab.label }}<span>{{ tab.id === 'discover' ? discoverProducts.length : ownedProducts.length }}</span></button></nav>
    <main :id="`content-store-panel-${activeTab}`" class="store-content" role="tabpanel" :aria-labelledby="`content-store-tab-${activeTab}`">
      <div v-if="loading && !account" class="store-state" aria-live="polite"><LoadingSpinner size="sm" /><p>Loading the GenStudio catalog…</p></div>
      <div v-else-if="!error && products.length === 0" class="store-state"><h2>The Content Store is ready, but no packs have been published yet.</h2><p>Refresh later to see the catalog GenStudio publishes for this account.</p></div>
      <div v-else-if="activeTab === 'owned' && ownedProducts.length === 0" class="store-state"><h2>No permanently owned packs yet</h2><p>Choose Discover to request an exact quote from GenStudio.</p></div>
      <template v-else><ContentStoreFilters :products="tabProducts" :query="query" :price="price" :kind="kind" :tag="tag" :compatible-only="compatibleOnly" @update:query="query = $event" @update:price="price = $event" @update:kind="kind = $event" @update:tag="tag = $event" @update:compatible-only="compatibleOnly = $event" /><div v-if="visibleShelves.length" class="shelf-list"><ContentStoreShelf v-for="shelf in visibleShelves" :key="shelf.shelf.id" :shelf="shelf.shelf" :products="shelf.products" :account="account" :busy-product-id="quoteBusyProduct" :busy-release-id="installBusyRelease" @quote="openQuote" @install="installRelease" /></div><div v-else class="store-state"><h2>No published products match these filters</h2><p>Clear a filter or try another catalog search.</p><button type="button" class="btn btn-secondary" @click="clearFilters">Clear filters</button></div></template>
      <section v-if="completedAttempts.length" class="ownership-history" aria-labelledby="ownership-heading"><h2 id="ownership-heading">Recent permanent ownership</h2><ul><li v-for="attempt in completedAttempts" :key="attempt.quote_id"><span>{{ productTitle(attempt.product_id) }}</span><span>Owned in GenStudio · install explicitly from the Owned shelf</span><span>{{ formatCredits(attempt.credits_charged ?? 0) }} credits charged</span></li></ul><p v-if="hasVerifiedOwnership">Ownership receipts are verified locally against GenStudio's published signing key.</p><p v-else>Use Restore purchases to verify this account's ownership receipts on this Mac.</p></section>
    </main>
    <ContentPurchaseDialog :visible="dialogOpen" :attempt="selectedAttempt" :product="selectedProduct" :error="dialogError" :busy="purchaseBusy" @close="closeDialog" @confirm="confirmPurchase" @retry="confirmPurchase" />
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, type ComponentPublicInstance } from 'vue'
import ContentStoreFilters, { type PriceFilter } from '~/components/content-store/ContentStoreFilters.vue'
import ContentStoreShelf from '~/components/content-store/ContentStoreShelf.vue'
import ContentPurchaseDialog from '~/components/content-store/ContentPurchaseDialog.vue'
import { filterCatalogProducts, orderShelfProducts, type ContentStoreKindFilter } from '~/content-store/catalog-presentation'
import type { ContentStoreProduct, ContentStoreUiError, PublicContentPurchaseAttempt } from '~/composables/useContentStore'

useAppTitle('Content Store')
type StoreTab = 'discover' | 'owned'
const tabs: Array<{ id: StoreTab; label: string }> = [{ id: 'discover', label: 'Discover' }, { id: 'owned', label: 'Owned' }]
const store = useContentStore(); const appSettingsModal = useAppSettingsModal(); const { account, products, shelves, attempts, loading, error } = store
const route = useRoute(); const viewingDetail = computed(() => typeof route.params.productId === 'string' && route.params.productId.length > 0)
const activeTab = ref<StoreTab>('discover'); const query = ref(''); const price = ref<PriceFilter>('all'); const kind = ref<ContentStoreKindFilter>('all'); const tag = ref(''); const compatibleOnly = ref(false)
const quoteBusyProduct = ref(''); const installBusyRelease = ref(''); const purchaseBusy = ref(false); const dialogOpen = ref(false); const selectedQuoteId = ref(''); const selectedProductId = ref(''); const dialogError = ref<ContentStoreUiError | null>(null); const tabRefs = new Map<StoreTab, HTMLButtonElement>()
const discoverProducts = computed(() => products.value.filter(product => !product.owned && !product.retired)); const ownedProducts = computed(() => products.value.filter(product => product.owned)); const tabProducts = computed(() => activeTab.value === 'discover' ? discoverProducts.value : ownedProducts.value)
const catalogPresentation = computed(() => Object.fromEntries(products.value.map(product => [product.productId, { productId: product.productId, ...product.presentation }])));
const filteredProducts = computed(() => filterCatalogProducts(tabProducts.value, query.value, { price: price.value, kind: kind.value, compatibleOnly: compatibleOnly.value, tag: tag.value || undefined }, catalogPresentation.value))
const visibleShelves = computed(() => { const visibleIds = new Set(filteredProducts.value.map(product => product.productId)); return shelves.value.map(shelf => ({ shelf, products: orderShelfProducts(products.value, shelf).filter(product => visibleIds.has(product.productId)) })).filter(shelf => shelf.products.length) })
const selectedAttempt = computed(() => attempts.value.find(row => row.quote_id === selectedQuoteId.value) || null); const selectedProduct = computed(() => products.value.find(row => row.productId === selectedProductId.value) || null); const completedAttempts = computed(() => attempts.value.filter(row => row.status === 'completed')); const hasVerifiedOwnership = computed(() => account.value?.owned.some(row => row.receiptVerification === 'verified') === true)
const pageError = computed(() => { if (!error.value || dialogOpen.value) return null; if (error.value.code === 'release_recalled') return { tone: 'warning', title: 'A Content Pack release was recalled', detail: error.value.recallReason ? `GenStudio stopped serving that exact version. Reason: ${error.value.recallReason} Ownership remains permanent; use the newest safe owned release when one is available.` : error.value.detail, showSettings: false }; if (error.value.code === 'signing_unavailable') return { tone: 'neutral', title: 'The Content Store is not open yet', detail: 'GenStudio cannot sign quotes right now. Nothing was purchased.', showSettings: false }; if (error.value.status === 401 || error.value.code === 'CONTENT_STORE_SCOPE_REQUIRED') return { tone: 'warning', title: 'The active key needs Content Store access', detail: error.value.detail, showSettings: true }; return { tone: 'warning', title: 'The Content Store is unavailable', detail: error.value.detail, showSettings: false } })
async function loadStore(): Promise<void> { try { await store.refresh() } catch { /* state renders the exact boundary */ } }
async function restoreOwnership(): Promise<void> { try { await store.restoreOwnership(); activeTab.value = 'owned' } catch { /* exact restore boundary is rendered from store.error */ } }
async function installRelease(releaseId: string): Promise<void> { if (installBusyRelease.value) return; installBusyRelease.value = releaseId; try { await store.installRelease(releaseId) } catch { /* exact install boundary is rendered from store.error */ } finally { installBusyRelease.value = '' } }
async function openQuote(product: ContentStoreProduct): Promise<void> { if (quoteBusyProduct.value) return; quoteBusyProduct.value = product.productId; dialogError.value = null; try { const attempt = await store.requestQuote(product.productId, product.currentRelease?.releaseId ?? null); selectedQuoteId.value = attempt.quote_id; selectedProductId.value = product.productId; dialogOpen.value = true } catch { /* a failed quote never opens the purchase dialog */ } finally { quoteBusyProduct.value = '' } }
async function confirmPurchase(quoteId: string): Promise<void> { if (purchaseBusy.value) return; purchaseBusy.value = true; dialogError.value = null; try { await store.confirmPurchase(quoteId) } catch { dialogError.value = error.value } finally { purchaseBusy.value = false } }
function closeDialog(): void { if (purchaseBusy.value) return; dialogOpen.value = false; selectedQuoteId.value = ''; selectedProductId.value = ''; dialogError.value = null }
function clearFilters(): void { query.value = ''; price.value = 'all'; kind.value = 'all'; tag.value = ''; compatibleOnly.value = false }
function setTabRef(id: StoreTab, element: Element | ComponentPublicInstance | null): void { if (element instanceof HTMLButtonElement) tabRefs.set(id, element); else tabRefs.delete(id) }
function moveTab(event: KeyboardEvent): void { if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const current = tabs.findIndex(tab => tab.id === activeTab.value); const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; const target = tabs[next]; if (!target) return; activeTab.value = target.id; tabRefs.get(target.id)?.focus() }
function productTitle(productId: string): string { return products.value.find(product => product.productId === productId)?.title || productId }
function formatCredits(value: number): string { return value.toLocaleString() }
onMounted(() => { void loadStore() })
</script>

<style scoped>
.content-store-page { width: min(1180px, calc(100% - 36px)); margin: 0 auto; padding: 30px 0 64px; color: var(--text-primary); }.store-header { display: flex; align-items: end; justify-content: space-between; gap: 24px; }.store-header h1 { font-size: clamp(32px, 4vw, 48px); letter-spacing: -.04em; line-height: 1.05; }.store-header p { max-width: 660px; margin-top: 10px; color: var(--text-secondary); font-size: var(--font-lg); line-height: 1.55; }.store-header-actions { display: flex; flex: 0 0 auto; gap: 8px; }.back-link { display: inline-block; margin-bottom: 8px; color: var(--text-secondary); font-size: var(--font-sm); text-decoration: underline; text-underline-offset: 4px; }
.account-strip { display: grid; grid-template-columns: minmax(180px, 1fr) auto; align-items: center; gap: 24px; margin-top: 24px; padding: 15px 18px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--bg-secondary); }.account-strip span, .account-strip dt { display: block; color: var(--text-muted); font-size: var(--font-xs); }.account-strip strong, .account-strip dd { overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }.account-strip dl { display: flex; gap: 20px; }.store-notice { margin-top: 18px; padding: 14px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--bg-secondary); }.store-notice.warning { border-color: color-mix(in srgb, var(--warning) 38%, var(--border)); }.store-notice strong { color: var(--warning); }.store-notice p { margin-top: 3px; color: var(--text-secondary); }.notice-action { margin-top: 8px; border: 0; background: transparent; color: var(--accent); cursor: pointer; font: inherit; font-weight: 650; text-decoration: underline; text-underline-offset: 3px; }
.store-tabs { display: flex; gap: 4px; margin-top: 24px; padding: 5px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--bg-secondary); }.store-tabs button { display: inline-flex; min-height: var(--control-height-sm); align-items: center; gap: 7px; padding: 7px 10px; border: 0; border-radius: var(--radius-md); background: transparent; color: var(--text-secondary); cursor: pointer; font: inherit; font-weight: 650; }.store-tabs button[aria-selected='true'] { background: var(--accent-dim); color: var(--text-primary); }.store-tabs span { color: var(--accent); font-size: var(--font-xs); font-variant-numeric: tabular-nums; }.store-content { display: grid; gap: 20px; margin-top: 18px; }.shelf-list { display: grid; gap: 28px; }.store-state { display: grid; justify-items: start; gap: 9px; padding: 26px; border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--bg-secondary); }.store-state h2 { font-size: var(--font-2xl); letter-spacing: -.02em; }.store-state p { color: var(--text-secondary); }.ownership-history { display: grid; gap: 12px; padding-top: 20px; border-top: 1px solid var(--border); }.ownership-history h2 { font-size: var(--font-xl); }.ownership-history ul { display: grid; gap: 8px; padding: 0; list-style: none; }.ownership-history li { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr) auto; gap: 12px; padding: 10px; border-radius: var(--radius-md); background: var(--bg-secondary); color: var(--text-secondary); font-size: var(--font-sm); }.ownership-history li span:last-child { font-variant-numeric: tabular-nums; text-align: right; }.ownership-history > p { color: var(--text-muted); font-size: var(--font-sm); }
@media (max-width: 720px) { .store-header { align-items: stretch; flex-direction: column; }.store-header-actions { flex-wrap: wrap; }.account-strip { grid-template-columns: 1fr; gap: 12px; }.account-strip dl { flex-wrap: wrap; }.ownership-history li { grid-template-columns: 1fr; gap: 3px; }.ownership-history li span:last-child { text-align: left; } } @media (max-width: 420px) { .content-store-page { width: min(100% - 24px, 1180px); padding-top: 20px; }.store-header-actions .btn { flex: 1 1 130px; justify-content: center; }.store-tabs { width: 100%; }.store-tabs button { flex: 1 1 0; justify-content: center; } }
</style>
